@startuml

class Customer {
  + Name
}

class Broker {
  + Name
}

class InsuranceProduct {
  + Name
}

class Offer {
  + Date
}

class Contract {
  + Date
  + Billing_Frequency
}

class Invoice {
  + Amount
  + Date
}

class ClaimCase {
  + Status
}

class Estimator {
  + Name
}

class EstimatorReport {
  + Date
  + Content
}

class CompensationDecision {
  + Eligible_Costs
  + Total_Sum
}

class Claim {
  + Date
}

Broker "1" -- "*" Customer : manages
Customer "1" -- "*" Offer : receives
Customer "1" -- "*" Contract : signs
Customer "1" -- "*" Claim : files
Customer "1" -- "1" CompensationDecision : receives
InsuranceProduct "1" -- "*" Offer : is subject of
InsuranceProduct "1" -- "*" Contract : is subject of
InsuranceProduct "1" -- "*" Invoice : determines price of
Contract "1" -- "*" Invoice : generates
Contract "1" -- "*" ClaimCase : triggers
ClaimCase "1" -- "*" Claim : involves
ClaimCase "1" -- "*" EstimatorReport : undergoes assessment
ClaimCase "1" -- "0..1" CompensationDecision : results in
Estimator "1" -- "*" EstimatorReport : issues

@enduml

